    // Cambia al cambiar la marca (otro ahora)
    const f4 = await firmarCuerpo(cuerpo, secretoValido, ahora + 5000);
    expect(f4.marca).not.toBe(f1.marca);
    expect(f4.firma).not.toBe(f1.firma);
  });

